+function segmentToRegex(segment: string): string {
+  let result = '';
+  for (let i = 0; i < segment.length; i++) {
+    const ch = segment[i];
+    if (ch === '*') {
+      if (i + 1 < segment.length && segment[i + 1] === '*') {
+        result += '[^/]*';
+        i++;
+      } else {
+        result += '[^/]*';
+      }
+    } else if (ch === '?') {
+      result += '[^/]';
+    } else if ('+^${}()|[\\].'.includes(ch)) {
+      result += '\\' + ch;
+    } else {
+      result += ch;
+    }
+  }
+  return result;
+}
+
+function compilePattern(pattern: string): { negate: boolean; regex: RegExp; raw: string } {
+  const negate = pattern.startsWith('!');
+  if (negate) {
+    pattern = pattern.slice(1);
+  }
+
+  const segments = pattern.split('/');
+  let regexStr = '^';
+
+  for (let i = 0; i < segments.length; i++) {
+    const seg = segments[i];
+    if (seg === '**') {
+      if (i === segments.length - 1) {
+        regexStr += '/.+';
+      } else if (i === 0) {
+        regexStr += '(?:[^/]+/)*';
+      } else {
+        regexStr += '(?:/[^/]+)*/';
+      }
+    } else {
+      if (i > 0 && segments[i - 1] !== '**') {
+        regexStr += '/';
+      }
+      regexStr += segmentToRegex(seg);
+    }
+  }
+
+  regexStr += '$';
+  return { negate, regex: new RegExp(regexStr), raw: pattern };
+}
+
 /** Selects paths with an ordered list of glob patterns. See README.md for the syntax. */
 export class PathMatcher
